#define P(n) st[n], st[n] > 1 ? "s" : ""
        if (file_printf(ms, " (%" SIZE_T_FORMAT "u object%s, %" SIZE_T_FORMAT
            "u array%s, %" SIZE_T_FORMAT "u string%s, %" SIZE_T_FORMAT
            "u constant%s, %" SIZE_T_FORMAT "u number%s, %" SIZE_T_FORMAT
